-- Three of Ocarina of Time Remake's adult trading items under the names the
-- remake gives them (Polygon's remake guide): Odd Potion is the Odd Poultice,
-- World's Finest Eye Drops the Specialty Eye Drops, and the Claim Check the
-- Biggoron Receipt. Each rename is kept in the marker's history as an edit by
-- user 15, after a first version of the marker as it was (lib/common/wiki.php
-- wikiEnsureBaseline, wikiRecordRevision), the versions written as they stood
-- in production on 2026-11-13. A marker changed since is left alone: each step
-- only applies while the marker still has its old name and last-edited time.
-- Odd Potion -> Odd Poultice
INSERT INTO marker_revision (marker_id, user_id, action, summary, reverts_revision_id, data, created) SELECT 64705042, 15, 'import', NULL, NULL, '{"title":"Odd Potion","description":"","categoryId":64063,"submapId":650001,"x":156.366,"y":-117.667,"z":null,"global":0,"visible":1,"tabs":["<p>Deliver the Odd Mushroom to the potion maker before time runs out.<\\/p><p><em>Adult Link<\\/em><\\/p>"]}', '2026-11-07 03:13:44' FROM DUAL WHERE EXISTS (SELECT 1 FROM marker WHERE id = 64705042 AND name = 'Odd Potion' AND last_updated = '2026-11-07 03:13:44') AND NOT EXISTS (SELECT 1 FROM marker_revision WHERE marker_id = 64705042);
INSERT INTO marker_revision (marker_id, user_id, action, summary, reverts_revision_id, data, created) SELECT 64705042, 15, 'edit', 'Renamed to the remake''s name, Odd Poultice', NULL, '{"title":"Odd Poultice","description":"","categoryId":64063,"submapId":650001,"x":156.366,"y":-117.667,"z":null,"global":0,"visible":1,"tabs":["<p>Deliver the Odd Mushroom to the potion maker before time runs out.<\\/p><p><em>Adult Link<\\/em><\\/p>"]}', NOW() FROM DUAL WHERE EXISTS (SELECT 1 FROM marker WHERE id = 64705042 AND name = 'Odd Potion' AND last_updated = '2026-11-07 03:13:44');
UPDATE marker SET name = 'Odd Poultice', last_updated = NOW() WHERE id = 64705042 AND name = 'Odd Potion' AND last_updated = '2026-11-07 03:13:44';
